<?php use App\Core\Csrf;$u=rtrim($_ENV['APP_URL']??'','/'); ?>
<div class="page-head"><div><span class="eyebrow">TIC · SOLICITUD</span><h1><?=htmlspecialchars($request['numero_solicitud'])?></h1><p><?=htmlspecialchars($request['nombre'])?> · <?=htmlspecialchars($request['numero_identificacion'])?></p></div><a class="btn secondary" href="<?=$u?>/admin/tic">← Bandeja</a></div>
<div class="grid-2"><div class="card"><h2>Datos de la solicitud</h2><dl class="detail-grid"><dt>Origen</dt><dd><?=htmlspecialchars($request['origen_codigo'])?></dd><dt>Tipo</dt><dd><?=htmlspecialchars($request['tipo'])?></dd><dt>Perfil</dt><dd><?=htmlspecialchars($request['perfil']??'—')?></dd><dt>Estado</dt><dd><?=htmlspecialchars($request['estado_codigo'])?></dd></dl></div>
<div class="card"><h2>Username institucional</h2><form method="post" action="<?=$u?>/admin/tic/usernames/validar"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="id" value="<?=$request['id']?>"><button class="btn">Generar / validar en Microsoft</button></form><div class="candidate-list"><?php foreach($usernames as $c):?><form method="post" action="<?=$u?>/admin/tic/usernames/seleccionar" class="candidate"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="id" value="<?=$request['id']?>"><input type="hidden" name="candidate_id" value="<?=$c['id']?>"><div><strong><?=htmlspecialchars($c['email_propuesto'])?></strong><small><?=htmlspecialchars($c['estado'])?><?= $c['detalle_validacion']?' · '.htmlspecialchars($c['detalle_validacion']):''?></small></div><?php if($c['estado_codigo']==='DISPONIBLE'&&!$c['seleccionado']):?><button class="btn small secondary">Seleccionar</button><?php elseif($c['seleccionado']):?><span class="status">Seleccionado</span><?php endif;?></form><?php endforeach;?></div></div></div>
<div class="card"><h2>Aprobar y provisionar</h2><p>La licencia se determina automáticamente según el perfil institucional.</p><div class="auto-license"><span>Licencia automática</span><strong><?=htmlspecialchars($automaticLicense['nombre']??'Sin política configurada')?></strong><small><?=!empty($automaticLicense['sku_externo'])?'SKU configurado: '.htmlspecialchars($automaticLicense['sku_externo']):'Configura el SKU antes de provisionar.'?></small></div><form id="provisionForm" method="post" action="<?=$u?>/admin/tic/provisionar"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="id" value="<?=$request['id']?>"><button type="button" class="btn" id="openProvisionModal" <?=empty($automaticLicense)||empty($automaticLicense['sku_externo'])?'disabled':''?>>Aprobar y provisionar</button></form></div>
<div class="orion-modal" id="provisionModal" aria-hidden="true"><div class="orion-modal-backdrop" data-modal-close></div><div class="orion-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="provisionTitle"><button type="button" class="orion-modal-x" data-modal-close aria-label="Cerrar">×</button><span class="eyebrow">CONFIRMAR PROVISIONAMIENTO</span><h2 id="provisionTitle">Crear cuenta institucional</h2><p>Se aprobará la solicitud de <strong><?=htmlspecialchars($request['nombre'])?></strong> y se provisionará su cuenta Microsoft 365.</p><div class="modal-summary"><span>Perfil</span><strong><?=htmlspecialchars($request['perfil']??'—')?></strong><span>Licencia</span><strong><?=htmlspecialchars($automaticLicense['nombre']??'—')?></strong></div><p class="muted">La contraseña inicial institucional deberá cambiarse obligatoriamente en el primer inicio.</p><div class="modal-actions"><button type="button" class="btn secondary" data-modal-close>Cancelar</button><button type="button" class="btn" id="confirmProvision">Sí, aprobar y provisionar</button></div></div></div>
<script>
(()=>{const modal=document.getElementById('provisionModal'),open=document.getElementById('openProvisionModal'),confirm=document.getElementById('confirmProvision'),form=document.getElementById('provisionForm');if(!modal||!open||!confirm||!form)return;const show=()=>{modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')};const hide=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')};open.addEventListener('click',show);modal.querySelectorAll('[data-modal-close]').forEach(x=>x.addEventListener('click',hide));document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});confirm.addEventListener('click',()=>{confirm.disabled=true;confirm.textContent='Provisionando…';form.submit()})})();
</script>
